function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 100) return 'grid needs 1 to 100 rows.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 1 || n > 100) return 'Each row needs 1 to 100 values.';
  for (let i = 0; i < grid.length; i++) {
    if (!Array.isArray(grid[i]) || grid[i].length !== n) return 'All rows must have the same length.';
    for (let j = 0; j < n; j++) {
      const v = grid[i][j];
      if (!Number.isInteger(v) || v < -100 || v > 100) return 'Each value is a whole number from -100 to 100.';
      if (j > 0 && v > grid[i][j - 1]) return 'Each row must be non-increasing from left to right.';
      if (i > 0 && v > grid[i - 1][j]) return 'Each column must be non-increasing from top to bottom.';
    }
  }
  return null;
}

