function countNegatives(grid) {
  const cols = grid[0].length;
  let count = 0;
  let limit = cols;
  for (const row of grid) {
    let left = 0;
    let right = limit;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (row[mid] < 0) {
        right = mid;
      } else {
        left = mid + 1;
      }
    }
    count += cols - left;
    limit = left;
  }
  return count;
}

