function generate(rand, size) {
  const large = size === 'large';
  const m = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  const n = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  // Each cell steps down from the smaller of its upper and left neighbours, so rows and columns never increase.
  const start = large ? 100 - Math.floor(rand() * 60) : Math.floor(rand() * 16) - 5;
  const maxStep = large ? 2 : 1 + Math.floor(rand() * 3);
  const grid = [];
  for (let i = 0; i < m; i++) {
    const row = [];
    for (let j = 0; j < n; j++) {
      let above = Infinity;
      if (i > 0) above = grid[i - 1][j];
      let before = Infinity;
      if (j > 0) before = row[j - 1];
      const base = i === 0 && j === 0 ? start : Math.min(above, before);
      const step = rand() < 0.4 ? 0 : Math.floor(rand() * (maxStep + 1));
      row.push(Math.max(-100, base - step));
    }
    grid.push(row);
  }
  return [grid];
}
